@push('scripts')<script>
const qualifications=@json($qualifications),availability=@json($availability),occupied=@json($meetings),day=@json($day);let selected=null;
function eligibleProfessors(){const subject=Number($('#booking-subject').val()),start=$('#booking-start').val(),end=$('#booking-end').val();$('#booking-professor option').each(function(){const id=Number(this.value),ok=qualifications.some(q=>q.professor_id===id&&q.subject_id===subject)&&availability.some(a=>a.professor_id===id&&a.day===day&&a.start_time.slice(0,5)<=start&&a.end_time.slice(0,5)>=end)&&!occupied.some(m=>m.professor_id===id&&m.start_time.slice(0,5)<end&&m.end_time.slice(0,5)>start);this.disabled=!ok;});if($('#booking-professor option:selected').prop('disabled'))$('#booking-professor').val($('#booking-professor option:not(:disabled)').first().val()??'');}
$('.subject-chip').on('click dragstart',function(e){selected=this.dataset.id;$('#booking-subject').val(selected);$('.subject-chip').attr('aria-pressed','false').removeClass('active');$(this).attr('aria-pressed','true').addClass('active');if(e.type==='dragstart')e.originalEvent.dataTransfer.setData('text/plain',selected);eligibleProfessors();});
$('.room-slot').on('dragover',e=>e.preventDefault()).on('click drop',function(e){e.preventDefault();if(selected)$('#booking-subject').val(selected);$('#booking-room').val(this.dataset.room);$('#booking-start').val(this.dataset.time);$('#booking-end').val(String(Number(this.dataset.time.slice(0,2))+1).padStart(2,'0')+':00');eligibleProfessors();document.getElementById('booking-form').scrollIntoView({behavior:'smooth',block:'center'});});
$('#booking-subject,#booking-start,#booking-end').on('change',eligibleProfessors);eligibleProfessors();$('#preview-booking').on('click',async function(){this.disabled=true;try{const body=new FormData(document.getElementById('booking-form'));body.set('preview','1');const response=await fetch('/scheduler/book',{method:'POST',body,headers:{Accept:'application/json'}}),data=await response.json();$('#booking-result').text(response.ok?data.message:Object.values(data.errors??{error:[data.message]}).flat().join(' '));}catch{$('#booking-result').text('Booking could not be checked. Try again.');}finally{this.disabled=false;}});
</script>@endpush
